   155:/* ═══════════════════════════════════════════════════════════════════════
   156:   Base
   157:   ═══════════════════════════════════════════════════════════════════════ */
   158::root {
   159:  font-family: var(--font-family-base);
   160:  color: var(--color-text-base);
   161:  background: var(--color-bg-base);
   162:  font-synthesis: none;
   163:}
   164:
   165:* { box-sizing: border-box; }
   166:body { margin: 0; min-width: 320px; }
   167:button { font: inherit; }
   168:button:focus-visible { outline: 3px solid var(--color-focus); outline-offset: 3px; }
