   170:/* ═══════════════════════════════════════════════════════════════════════
   171:   App shell & world themes
   172:   ═══════════════════════════════════════════════════════════════════════ */
   173:/* The app is one phone-width column. Everything inside is positioned against it, never the window. */
   174:.app-shell {
   175:  /* Top of the name and settings button; never under the notch. */
   176:  --top-pad: max(30px, env(safe-area-inset-top));
   177:  /* Space reserved once for the overlaid top bar and nav dock; layouts read these instead of magic offsets.
   178:     The top bar includes the toast slot under the hearts, so toasts and the tap bubble sit above a dog standing on a card. */
   179:  --top-bar-space: calc(var(--top-pad) + 112px);
   180:  --nav-space: calc(max(8px, env(safe-area-inset-bottom)) + 124px);
   181:  /* One slot for toasts and the tap-the-dog bubble: just under the name and hearts, centred over the scene. */
   182:  --toast-top: calc(var(--top-pad) + 76px);
   183:  --overlay-center: 50%;
   184:  --overlay-max-width: calc(100% - 32px);
   185:  --chip-h: 46px;
   186:  /* The dog layer may start this high, under the top bar; --top-overlap is how much of it the top bar covers. */
   187:  --stage-top: max(12px, env(safe-area-inset-top));
   188:  --top-overlap: calc(var(--top-bar-space) - var(--stage-top));
   189:  --side-gutter: 14px;
   190:  position: relative;
   191:  z-index: 1;
   192:  width: 100%;
   193:  max-width: 430px;
   194:  height: 100dvh;
   195:  margin: 0 auto;
   196:  overflow: hidden;
   197:  background: var(--color-bg-shell);
   198:}
   199:.app-shell.world-flat { --world-tint: linear-gradient(rgba(113, 86, 61, .26), rgba(60, 75, 57, .14)); }
   200:.app-shell.world-garden { --world-tint: linear-gradient(rgba(65, 111, 58, .05), rgba(34, 79, 46, .08)); }
   201:.app-shell.world-kampung { --world-tint: linear-gradient(rgba(222, 143, 60, .22), rgba(74, 89, 44, .18)); }
   202:.world-flat .scene-shade { background: linear-gradient(180deg, rgba(62,46,32,.48), transparent 26%, rgba(245,213,170,.1) 55%, rgba(46,53,39,.4)); }
   203:.world-kampung .scene-shade { background: linear-gradient(180deg, rgba(95,48,28,.25), rgba(255,180,85,.06) 32%, transparent 55%, rgba(59,45,25,.42)); }
   204:
   205:.scene-shade {
   206:  position: absolute;
   207:  inset: 0;
   208:  pointer-events: none;
   209:  background: linear-gradient(180deg, rgba(22, 54, 38, .4) 0%, transparent 22%, transparent 45%, rgba(15, 36, 26, .1) 68%, rgba(15, 36, 26, .36) 100%);
   210:}
   211:
   212:/* Lawn marker: the dog's ground line on landscape screens without chips (see DOG_PLACEMENTS.lawn). Unused in portrait. */
   213:.scene-ground { position: absolute; left: 0; right: 0; bottom: 0; height: 0; pointer-events: none; }
