   215:/* ═══════════════════════════════════════════════════════════════════════
   216:   Top zone
   217:   ═══════════════════════════════════════════════════════════════════════ */
   218:.top-zone {
   219:  position: absolute;
   220:  z-index: 20;
   221:  top: 0;
   222:  left: 0;
   223:  width: 100%;
   224:  display: flex;
   225:  justify-content: space-between;
   226:  align-items: flex-start;
   227:  padding: var(--top-pad) 28px 12px;
   228:  color: white;
   229:  text-shadow: var(--shadow-top-zone);
   230:}
   231:
   232:/* Name + hearts: one button back to Home, styled as plain text. */
   233:.top-zone__home { display: block; padding: 0; border: 0; border-radius: var(--radius-sm); color: inherit; background: none; text-align: left; text-shadow: inherit; cursor: pointer; }
   234:.dog-name { display: block; margin: 0; font-size: var(--font-size-9xl); line-height: 1; font-weight: var(--font-weight-black); letter-spacing: -1.4px; }
   235:.hearts { display: flex; gap: 2px; margin-top: 7px; color: var(--color-accent-heart); font-size: 28px; line-height: .92; filter: var(--shadow-hearts); }
   236:.heart-empty { color: white; }
   237:.glass-button, .scene-chip {
   238:  border: 1px solid rgba(255,255,255,.4);
   239:  color: white;
   240:  background: var(--color-surface-glass);
   241:  backdrop-filter: blur(16px);
   242:  box-shadow: var(--shadow-glass);
   243:}
   244:.glass-button { display: grid; place-items: center; width: 52px; height: 52px; margin-top: 5px; border-radius: var(--radius-full); cursor: pointer; }
   245:
   246:/* ═══════════════════════════════════════════════════════════════════════
   247:   Screen stage & home card
   248:   ═══════════════════════════════════════════════════════════════════════ */
   249:.screen-stage { position: absolute; z-index: 2; inset: 0; }
   250:.eyebrow { margin: 0 0 4px; font-size: var(--font-size-base); font-weight: var(--font-weight-black); letter-spacing: 1.5px; text-transform: uppercase; }
   251:.eyebrow.green { color: var(--color-text-eyebrow-green); }
   252:
   253:/* Home: a stacked column between the top bar and the nav. Stage grows, chips and card keep their own height. */
   254:.home-layout {
   255:  position: absolute;
   256:  inset: 0;
   257:  display: flex;
   258:  flex-direction: column;
   259:  gap: 10px;
   260:  padding: var(--top-bar-space) var(--side-gutter) var(--nav-space);
   261:  overflow-y: auto;
   262:  overscroll-behavior: contain;
   263:  scrollbar-width: none;
   264:}
   265:.home-layout::-webkit-scrollbar { display: none; }
   266:/* Empty spacer: the shared dog layer stands on the chips below it. Keeps room for at least --dog-min (it may reach under the top bar). */
   267:.home-layout__stage { flex: 1 1 auto; min-height: max(0px, calc(var(--dog-min, 0px) - var(--top-overlap))); }
   268:.home-layout__chips {
   269:  flex: none;
   270:  /* Bottom row: the chips' top edge is the dog's ground line. */
   271:  display: flex;
   272:  justify-content: space-between;
   273:  padding-inline: 14px;
   274:}
   275:.scene-actions { display: flex; gap: 8px; }
   276:/* Portrait: the cards are plain items of the Home column. Landscape turns this into the right-hand pane. */
   277:.home-layout__cards { display: contents; }
   278:.scene-chip { position: relative; height: var(--chip-h); padding: 0 14px; display: flex; align-items: center; gap: 7px; border-radius: var(--radius-pill); font-size: var(--font-size-3xl); font-weight: var(--font-weight-black); cursor: pointer; }
   279:.gift-chip { width: 42px; justify-content: center; padding: 0; }
   280:.badge-dot { position: absolute; top: 2px; right: 2px; width: 10px; height: 10px; border-radius: var(--radius-full); background: var(--color-accent-badge); border: 2px solid white; }
   281:
   282:.content-card {
   283:  position: absolute;
   284:  z-index: 4;
   285:  left: var(--side-gutter);
   286:  right: var(--side-gutter);
   287:  bottom: var(--nav-space);
   288:  border-radius: var(--radius-9xl);
   289:  padding: 24px 20px 18px;
   290:  background: var(--color-surface-card);
   291:  box-shadow: var(--shadow-card);
   292:}
   293:.home-layout .home-card { position: relative; flex: none; left: auto; right: auto; bottom: auto; }
   294:.card-heading { display: flex; align-items: center; justify-content: space-between; gap: 18px; margin-bottom: 16px; }
   295:.content-card h2 { margin: 0; color: var(--color-text-heading); font-size: var(--font-size-7xl); line-height: 1.1; font-weight: var(--font-weight-black); letter-spacing: -.6px; }
   296:.progress-copy { flex: none; color: #6c806f; font-size: var(--font-size-base); font-weight: var(--font-weight-bold); }
   297:
   298:/* ═══════════════════════════════════════════════════════════════════════
   299:   Med list & home actions
   300:   ═══════════════════════════════════════════════════════════════════════ */
   301:.med-list { display: grid; gap: 5px; }
   302:.med-row { display: grid; grid-template-columns: 58px 36px 1fr auto; align-items: center; gap: 7px; min-height: 62px; padding: 8px 0; border-top: 1px solid var(--color-border-row); transition: opacity .2s; }
   303:.home-card .med-row { min-height: 50px; padding: 4px 0; }
   304:.home-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin: -4px 0 8px; }
   305:.home-actions button { min-width: 0; display: grid; grid-template-columns: 34px 1fr; align-items: center; gap: 7px; padding: 8px; border: 0; border-radius: var(--radius-xl); color: #315743; background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   306:.home-actions button:nth-child(2) { color: #945f45; background: var(--color-surface-cream-alt); }
   307:.home-actions button > span { display: grid; place-items: center; width: 34px; height: 34px; border-radius: var(--radius-sm); background: rgba(255,255,255,.72); }
   308:.home-actions button div { min-width: 0; display: grid; }
   309:.home-actions strong { overflow: hidden; font-size: var(--font-size-md); text-overflow: ellipsis; white-space: nowrap; }
   310:.home-actions small { overflow: hidden; color: #79867e; font-size: var(--font-size-2xs); text-overflow: ellipsis; white-space: nowrap; }
   311:.med-row time { font-size: var(--font-size-base); color: #6f7d73; font-weight: var(--font-weight-bold); }
   312:.med-icon, .feature-icon { display: grid; place-items: center; width: 36px; height: 36px; border-radius: var(--radius-md); color: var(--color-accent-icon); background: var(--color-accent-icon-bg); }
   313:.med-copy { min-width: 0; }
   314:.med-copy h3, .alert-card h3, .next-dose h3, .timeline h3 { margin: 0; font-size: var(--font-size-xl); font-weight: var(--font-weight-black); }
   315:.med-copy p, .alert-card p, .next-dose p, .timeline p { margin: 1px 0 0; color: var(--color-text-muted); font-size: var(--font-size-md); }
   316:.taken-button { min-width: 58px; min-height: 36px; display: grid; place-items: center; border: 0; border-radius: var(--radius-lg); color: white; background: var(--color-primary-deep); font-size: var(--font-size-md); font-weight: var(--font-weight-black); cursor: pointer; }
   317:.is-taken { opacity: .58; }
   318:.is-taken .taken-button { color: #426c58; background: var(--color-surface-sage-dark); }
