   353:.bottom-nav button { width: 68px; height: 58px; display: grid; place-items: center; gap: 0; border: 0; border-radius: var(--radius-full); color: var(--color-text-nav-inactive); background: transparent; cursor: pointer; }
   354:.bottom-nav button span { font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   355:.bottom-nav button.active { color: var(--color-text-nav-active); background: white; box-shadow: var(--shadow-nav-active); }
   356:.add-button { position: absolute; z-index: 31; right: 29px; bottom: max(26px, calc(env(safe-area-inset-bottom) + 14px)); width: 68px; height: 68px; display: grid; place-items: center; border: 0; border-radius: var(--radius-full); color: white; background: var(--color-action-add); box-shadow: var(--shadow-add); cursor: pointer; }
   357:.companion-button svg { fill: currentColor; stroke-width: 1.4; }
   358:.woof-bubble { position: absolute; z-index: 32; right: 23px; bottom: max(100px, calc(env(safe-area-inset-bottom) + 88px)); padding: 6px 10px; border-radius: 12px 12px 3px 12px; color: #24372d; background: white; box-shadow: var(--shadow-woof); font-size: var(--font-size-sm); font-weight: var(--font-weight-black); transform: rotate(-4deg); }
   359:
   360:/* ═══════════════════════════════════════════════════════════════════════
   361:   Full card (shared by sub-screens)
   362:   ═══════════════════════════════════════════════════════════════════════ */
   363:/*
   364: * --ledge-space is set while the dog stands on this card's top edge (see useSceneGround).
   365: * The card is a fixed frame (white, rounded, padding kept) holding the back button; only .full-card__scroll scrolls,
   366: * so scrolled content is clipped inside the frame instead of running into the card's edge. (FullCard.tsx)
   367: */
   368:.full-card { top: calc(var(--top-bar-space) + var(--ledge-space, -12px)); display: flex; flex-direction: column; overflow: hidden; }
   369:.full-card > .back-button { flex: none; align-self: flex-start; }
   370:/* Spans the frame's side padding (negative margin + padding) so focus rings and shadows aren't clipped at the content edge. */
   371:.full-card__scroll { flex: 1 1 auto; min-height: 0; margin-inline: -20px; padding: 8px 20px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: none; }
   372:.full-card__scroll::-webkit-scrollbar { display: none; }
   373:.back-button { display: flex; align-items: center; gap: 5px; margin: -5px 0 14px -5px; padding: 5px; border: 0; color: var(--color-text-back); background: transparent; font-weight: var(--font-weight-bold); cursor: pointer; }
   374:.streak-line { margin: 6px 0 0; color: var(--color-text-body); font-size: var(--font-size-lg); font-weight: var(--font-weight-bold); }
   375:.supporting { max-width: 430px; margin: 10px 0 22px; color: var(--color-text-body); font-size: var(--font-size-lg); line-height: 1.45; }
   376:.score-orb { flex: none; display: grid; place-items: center; width: 57px; height: 57px; border-radius: var(--radius-full); color: #204a36; background: var(--color-accent-score); font-weight: var(--font-weight-black); }
   377:
   378:/* ═══════════════════════════════════════════════════════════════════════
   379:   Alert / next-dose / section title / care grid
   380:   ═══════════════════════════════════════════════════════════════════════ */
   381:.alert-card, .next-dose { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 13px; padding: 15px; border-radius: var(--radius-5xl); }
   382:.alert-card.warm { background: var(--color-surface-cream-warm); }
   383:.alert-card small, .next-dose small, .field small { color: #9e664e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   384:.section-title { display: flex; justify-content: space-between; align-items: center; margin: 22px 2px 12px; }
   385:.section-title h3 { margin: 0; font-size: var(--font-size-2xl); font-weight: var(--font-weight-black); }
   386:.section-title button, .section-title span { border: 0; color: var(--color-text-body); background: transparent; font-size: var(--font-size-md); font-weight: var(--font-weight-bold); }
   387:.care-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   388:.care-grid article { display: grid; gap: 5px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   389:.care-grid article span { color: #5c8069; }
   390:.care-grid strong { font-size: var(--font-size-5xl); font-weight: var(--font-weight-black); }
   391:.care-grid small { color: var(--color-text-body); font-size: var(--font-size-sm); }
   392:
   393:/* ═══════════════════════════════════════════════════════════════════════
   394:   Activity card / role strip
   395:   ═══════════════════════════════════════════════════════════════════════ */
   396:.activity-card { margin-top: 10px; padding: 15px; border: 1px solid var(--color-border-card); border-radius: var(--radius-3xl); }
   397:.activity-card p { margin: 0; color: var(--color-text-body); font-size: var(--font-size-md); }
   398:.activity-card p:first-child { display: flex; justify-content: space-between; margin-bottom: 5px; color: #274538; }
   399:.decision-log-card details { margin-top: 8px; color: #52685a; font-size: var(--font-size-sm); }
   400:.decision-log-card summary { cursor: pointer; font-weight: 700; }
   401:.decision-log-card dl { display: grid; grid-template-columns: 92px 1fr; gap: 5px 8px; margin: 10px 0 0; }
   402:.decision-log-card dt { font-weight: 700; text-transform: capitalize; }
   403:.decision-log-card dd { margin: 0; overflow-wrap: anywhere; }
   404:.decision-observation { display: contents; }
   405:.demo-clock-card { display: grid; gap: 9px; margin-top: 18px; padding: 16px; border: 1px solid var(--color-border-card); border-radius: var(--radius-3xl); background: #fffdf8; }
   406:.demo-clock-card h3, .demo-clock-card p { margin: 0; }
   407:.demo-clock-card > p:not(.eyebrow) { color: #78857c; font-size: var(--font-size-sm); line-height: 1.4; }
   408:.demo-clock-card label { color: #52685a; font-size: var(--font-size-sm); font-weight: 700; }
   409:.demo-clock-card input { min-height: 48px; padding: 8px 10px; border: 1px solid var(--color-border-card); border-radius: 14px; color: #294a3a; font: inherit; }
   410:.demo-clock-card select { min-height: 48px; padding: 8px 10px; border: 1px solid var(--color-border-card); border-radius: 14px; color: #294a3a; background: white; font: inherit; }
   411:.demo-clock-card .consent-toggle { display: flex; align-items: flex-start; gap: 10px; line-height: 1.35; }
   412:.demo-clock-card .consent-toggle input { width: 22px; min-height: 22px; margin: 0; accent-color: #668b70; }
   413:.demo-clock-card .primary-button { margin-top: 2px; }
   414:.role-strip { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 10px; margin-bottom: 12px; padding: 12px 14px; border-radius: var(--radius-3xl); color: #426653; background: var(--color-surface-sage-light); }
   415:.role-strip div { display: grid; }
   416:.role-strip small { color: #76847b; font-size: var(--font-size-sm); }
   417:.role-strip > span { padding: 5px 8px; border-radius: var(--radius-pill); color: #4f765e; background: white; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   418:
   419:.next-dose { margin-top: 20px; background: var(--color-surface-sage-light); }
   420:.feature-icon.sage { color: var(--color-accent-sage-icon); background: var(--color-accent-sage-bg); }
