   422:/* ═══════════════════════════════════════════════════════════════════════
   423:   Timeline
   424:   ═══════════════════════════════════════════════════════════════════════ */
   425:.timeline { position: relative; display: grid; gap: 8px; }
   426:.timeline article { display: grid; grid-template-columns: 14px 54px 1fr auto; align-items: center; gap: 8px; min-height: 60px; }
   427:.timeline article:not(:last-child)::before { content: ""; position: absolute; left: 6px; height: 68px; margin-top: 66px; border-left: 2px solid var(--color-border-timeline); }
   428:.timeline-dot { z-index: 1; width: 13px; height: 13px; border: 3px solid var(--color-border-dot); border-radius: var(--radius-full); background: var(--color-surface-white); }
   429:.timeline-dot.complete { border-color: var(--color-accent-timeline); background: var(--color-accent-timeline); }
   430:.timeline time { color: var(--color-text-body); font-size: var(--font-size-sm); font-weight: var(--font-weight-bold); }
   431:
   432:/* ═══════════════════════════════════════════════════════════════════════
   433:   Status tag / primary button
   434:   ═══════════════════════════════════════════════════════════════════════ */
   435:.status-tag { padding: 6px 9px; border-radius: var(--radius-pill); color: var(--color-status-default); background: var(--color-status-default-bg); font-size: var(--font-size-xs); font-weight: var(--font-weight-black); }
   436:.status-tag.now { color: var(--color-status-now); background: var(--color-status-now-bg); }
   437:.primary-button { width: 100%; min-height: 52px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 18px; border: 0; border-radius: var(--radius-3xl); color: white; background: var(--color-primary); font-weight: var(--font-weight-black); text-decoration: none; cursor: pointer; box-shadow: var(--shadow-primary); }
