   459:/* ═══════════════════════════════════════════════════════════════════════
   460:   Fields / proof
   461:   ═══════════════════════════════════════════════════════════════════════ */
   462:.field, .field-row { padding: 14px; border-radius: var(--radius-xl); background: var(--color-surface-sage); }
   463:.field { display: grid; gap: 3px; }
   464:.field small { color: #6e886f; }
   465:.field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; padding: 0; background: transparent; }
   466:.proof-scanner.captured { color: #315a43; background: var(--color-surface-sage-darker); }
   467:.proof-check { z-index: 1; display: grid; place-items: center; width: 70px; height: 70px; border-radius: var(--radius-full); color: white; background: var(--color-accent-proof); box-shadow: var(--shadow-proof); }
   468:
   469:.scanner.scanning .camera-orb { animation: pulse 1s ease-in-out infinite; }
   470:.ocr-preview { margin-top: 14px; text-align: left; padding: 10px 14px; border-radius: var(--radius-3xl); background: var(--color-surface-sage); }
   471:.ocr-preview small { color: var(--color-text-faint); font-size: var(--font-size-xs); text-transform: uppercase; letter-spacing: .04em; }
   472:.ocr-preview p { margin-top: 4px; color: var(--color-text-body); font-size: var(--font-size-sm); line-height: 1.4; }
   473:@keyframes pulse { 0%, 100% { transform: scale(1); opacity: 1; } 50% { transform: scale(1.15); opacity: .7; } }
