   548:/* ═══════════════════════════════════════════════════════════════════════
   549:   Health / metric / weekly
   550:   ═══════════════════════════════════════════════════════════════════════ */
   551:.metric-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 18px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-cream); }
   552:.metric-card.complete { background: var(--color-surface-sage-deep); }
   553:.metric-card h3 { margin: 2px 0; font-size: var(--font-size-2xl); }
   554:.metric-card p { margin: 0; color: #78847c; font-size: var(--font-size-sm); }
   555:.metric-card small { color: #8b6b4e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   556:.metric-card > button { min-width: 46px; height: 38px; display: grid; place-items: center; border: 0; border-radius: var(--radius-md); color: white; background: var(--color-primary-camera); font-size: var(--font-size-md); font-weight: var(--font-weight-black); cursor: pointer; }
   557:.weekly-card { margin: 12px 0; padding: 17px; border-radius: var(--radius-6xl); background: var(--color-surface-sage); }
   558:.weekly-card .card-heading { margin-bottom: 10px; }
   559:.weekly-card h3 { margin: 0; font-size: var(--font-size-3xl); }
   560:.weekly-card p { color: #6d7d73; font-size: var(--font-size-md); line-height: 1.5; }
   561:.weekly-card > strong { display: block; padding: 10px; border-radius: var(--radius-sm); color: #5d6f63; background: white; font-size: var(--font-size-sm); }
   562:.health-bubble { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 12px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #294a3a; background: white; text-align: left; cursor: pointer; }
   563:.health-bubble div { display: grid; gap: 2px; }
   564:.health-bubble small { color: #7a847c; font-size: var(--font-size-sm); }
   565:.treatment-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-bottom: 10px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); }
   566:.treatment-card div { display: grid; gap: 2px; }
   567:.treatment-card small { color: #7a847c; font-size: var(--font-size-sm); }
   568:.treatment-card button { padding: 7px 10px; border: 0; border-radius: var(--radius-xs); color: #4f6d5c; background: #e8efe4; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); cursor: pointer; }
   569:.screening-card { margin-bottom: 10px; background: var(--color-surface-cream-warm); }
   570:.activity-link { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #284538; text-decoration: none; }
