   829:
   830:.dedication-card {
   831:  position: relative;
   832:  z-index: 3;
   833:  display: flex;
   834:  flex-direction: column;
   835:  align-items: center;
   836:  gap: 16px;
   837:  padding: 44px 56px;
   838:  animation: dedication-card-rise 0.4s cubic-bezier(0.22, 0.61, 0.36, 1) 0.05s both;
   839:}
   840:
   841:.dedication-rule {
   842:  display: block;
   843:  width: 32px;
   844:  height: 1px;
   845:  background: linear-gradient(90deg, transparent, rgba(255, 202, 116, 0.6), transparent);
   846:}
   847:
   848:.dedication-text {
   849:  margin: 0;
   850:  font-family: var(--font-family-letter);
   851:  font-size: clamp(1.75rem, 8vw, 2.25rem);
   852:  font-weight: 400;
   853:  font-style: normal;
   854:  letter-spacing: 0;
   855:  color: rgba(255, 253, 247, 0.96);
   856:  text-shadow: 0 2px 20px rgba(20, 40, 28, 0.5);
   857:}
   858:
   859:/* Animations */
   860:
   861:@keyframes cover-rise {
   862:  from { opacity: 0; transform: scale(1.04); }
   863:  to   { opacity: 1; transform: scale(1); }
   864:}
   865:
   866:@keyframes cover-zoom {
   867:  from { transform: scale(1); }
   868:  to   { transform: scale(1.08); }
   869:}
   870:
   871:@keyframes cta-breathe {
   872:  0%, 100% { transform: scale(1); opacity: 0.92; }
   873:  50%      { transform: scale(1.04); opacity: 1; }
   874:}
   875:
   876:@keyframes pulse-ring {
   877:  0%   { transform: translate(-50%, -50%) scale(0.6); opacity: 0.8; }
   878:  100% { transform: translate(-50%, -50%) scale(1.4); opacity: 0; }
   879:}
   880:
   881:@keyframes dedication-fade-in {
   882:  from { opacity: 0; }
   883:  to   { opacity: 1; }
   884:}
   885:
   886:@keyframes dedication-card-rise {
   887:  from { opacity: 0; transform: translateY(12px); }
   888:  to   { opacity: 1; transform: translateY(0); }
   889:}
   890:
   891:@keyframes glow-breathe {
   892:  0%, 100% { opacity: 0.6; transform: translate(-50%, -50%) scale(1); }
   893:  50%      { opacity: 1; transform: translate(-50%, -50%) scale(1.1); }
   894:}
   895:
   896:@media (prefers-reduced-motion: reduce) {
   897:  .intro-cover,
   898:  .intro-cover-img,
   899:  .intro-cover-cta,
   900:  .intro-cover-pulse,
   901:  .intro-dedication,
   902:  .intro-dedication-glow,
   903:  .dedication-card {
   904:    animation: none !important;
   905:  }
   906:  .dedication-card {
   907:    opacity: 1;
   908:    transform: none;
   909:  }
   910:  .intro-dedication {
   911:    opacity: 1;
   912:  }
   913:}
   914:
   915:/* ═══════════════════════════════════════════════════════════════════════
   916:   Landscape: two columns
   917:   ────────────────────────────────────────────────────────────────────────
   918:   Phones and tablets held sideways (touch), and any short landscape window.
   919:   Keep this query in sync with LANDSCAPE_MEDIA_QUERY in config/scene.ts: the dog's placement follows it.
   920:   Left column: garden, top bar, dog and Home's chips. Right pane: the screen's card (scrolling inside),
   921:   with the nav and paw button below it; the blurred garden (DesktopBackdrop) shows behind the pane.
   922:   A desktop with a mouse never matches, so it keeps the centred 430 px column.
   923:   ═══════════════════════════════════════════════════════════════════════ */
   924:@media (orientation: landscape) and (hover: none) and (pointer: coarse), (orientation: landscape) and (max-height: 520px) {
   925:  .app-shell {
   926:    /* Right pane: never narrower than a 360 px phone's card, never wider than a roomy one.
   927:       vw, not %: the shell is full-width here, and % would resolve against each element's own container. */
   928:    --pane-w: clamp(360px, 48vw, 480px);
   929:    --pane-top: max(12px, env(safe-area-inset-top));
   930:    --scene-bottom: max(12px, env(safe-area-inset-bottom));
   931:    --top-pad: max(clamp(12px, 3dvh, 30px), env(safe-area-inset-top));
   932:    /* A slightly lower dock so the card keeps more height on short screens. */
   933:    --nav-space: calc(max(8px, env(safe-area-inset-bottom)) + 110px);
   934:    --overlay-center: calc((100% - var(--pane-w)) / 2);
   935:    --overlay-max-width: calc(100% - var(--pane-w) - 32px);
   936:    max-width: none;
   937:    background: transparent;
   938:  }
