   475:/* ═══════════════════════════════════════════════════════════════════════
   476:   Plain card / explain points / listen button
   477:   ═══════════════════════════════════════════════════════════════════════ */
   478:.plain-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 20px; padding: 16px; border-radius: var(--radius-6xl); background: var(--color-surface-cream-warm); }
   479:.plain-card h3 { margin: 2px 0 0; font-size: var(--font-size-4xl); }
   480:.plain-card small { color: #9d654d; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   481:.plain-card > button { width: 46px; height: 46px; display: grid; place-items: center; border: 0; border-radius: var(--radius-full); color: white; background: var(--color-action-stop); cursor: pointer; }
   482:.explain-points { display: grid; margin-top: 14px; border: 1px solid var(--color-border-explain); border-radius: var(--radius-5xl); overflow: hidden; }
   483:.explain-points article { padding: 13px 15px; border-bottom: 1px solid var(--color-border-explain); }
   484:.explain-points article:last-child { border: 0; }
   485:.explain-points strong { font-size: var(--font-size-base); }
   486:.explain-points p { margin: 3px 0 0; color: var(--color-text-body); font-size: var(--font-size-base); line-height: 1.4; }
   487:.listen-button { width: 100%; min-height: 46px; display: flex; align-items: center; justify-content: center; gap: 8px; margin-top: 12px; border: 1px solid var(--color-border-listen); border-radius: var(--radius-xl); color: #496d59; background: #f4f6f0; font-weight: var(--font-weight-black); cursor: pointer; }
   488:
   489:/* ═══════════════════════════════════════════════════════════════════════
   490:   Schedule / dog message
   491:   ═══════════════════════════════════════════════════════════════════════ */
   492:.schedule-choice { display: grid; grid-template-columns: 72px 1fr auto; align-items: center; gap: 3px 10px; margin-top: 10px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-sage); }
   493:.schedule-choice span { grid-row: span 2; color: #6b7c70; font-size: var(--font-size-md); font-weight: var(--font-weight-black); text-transform: uppercase; }
   494:.schedule-choice strong { font-size: var(--font-size-4xl); }
   495:.schedule-choice small { color: var(--color-text-body); }
   496:.schedule-choice > svg { grid-column: 3; grid-row: 1 / span 2; }
   497:.dog-message { display: flex; align-items: center; gap: 12px; margin-top: 16px; padding: 13px; border-radius: var(--radius-3xl); color: #496a57; background: var(--color-surface-cream); }
   498:.dog-message p { margin: 0; color: #6f776f; font-size: var(--font-size-md); line-height: 1.4; }
   499:.dog-message strong { color: #4a594e; }
   500:
   501:/* ═══════════════════════════════════════════════════════════════════════
   502:   Walk screen
   503:   ═══════════════════════════════════════════════════════════════════════ */
   504:.walk-card { text-align: center; }
   505:.walk-card .back-button, .walk-card .eyebrow { text-align: left; }
   506:.walk-orb { width: 190px; height: 190px; margin: 23px auto; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; border: 10px solid var(--color-accent-walk-border-idle); border-radius: var(--radius-full); color: #446a55; background: #f2f5ed; transition: border-color .3s, transform .3s; }
   507:.walk-orb.active { border-color: var(--color-accent-walk-border); transform: scale(1.02); }
   508:.walk-orb strong { color: #193c2e; font-size: var(--font-size-8xl); font-weight: var(--font-weight-black); }
   509:.walk-orb small { color: #75847a; font-size: var(--font-size-sm); }
   510:.walk-stats { display: grid; grid-template-columns: repeat(3, 1fr); margin: 0 0 8px; }
   511:.walk-stats div { display: grid; gap: 2px; border-right: 1px solid #e0e5dc; }
   512:.walk-stats div:last-child { border: 0; }
   513:.walk-stats strong { font-size: var(--font-size-4xl); font-weight: var(--font-weight-black); }
   514:.walk-stats small { color: #79857e; font-size: var(--font-size-xs); text-transform: uppercase; }
   515:.stop-button { background: var(--color-action-stop); }
   516:.walk-note { color: #7b887f; font-size: var(--font-size-sm); }
   517:.gentle-note { margin: 8px auto 0; max-width: 330px; color: #88928b; font-size: var(--font-size-sm); line-height: 1.4; }
   518:.walk-orb.done { border-color: var(--color-accent-walk-border); }
   519:.walk-done { margin: 0 auto 12px; max-width: 330px; color: #315a43; font-size: var(--font-size-xl); font-weight: var(--font-weight-black); line-height: 1.4; }
   520:.walk-dizzy { margin: 10px auto 0; max-width: 330px; color: #9d543b; font-size: var(--font-size-sm); font-weight: var(--font-weight-bold); line-height: 1.4; }
   521:
   522:/* ═══════════════════════════════════════════════════════════════════════
   523:   World card / customize / tricks
   524:   ═══════════════════════════════════════════════════════════════════════ */
   525:.world-card { position: relative; margin-top: 18px; padding: 22px; border-radius: var(--radius-7xl); color: white; background: linear-gradient(135deg, #4f7654, #8aa36d); overflow: hidden; }
   526:.world-card::after { content: ""; position: absolute; width: 150px; height: 150px; right: -40px; bottom: -85px; border: 18px solid rgba(255,255,255,.12); border-radius: var(--radius-full); }
   527:.world-card h3 { margin: 5px 0 2px; font-size: var(--font-size-6xl); }
   528:.world-card p { margin: 0; color: rgba(255,255,255,.78); font-size: var(--font-size-md); }
   529:.world-level { font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1.5px; }
   530:.world-progress { height: 7px; margin-top: 18px; border-radius: 9px; background: rgba(255,255,255,.22); overflow: hidden; }
   531:.world-progress span { display: block; width: 100%; height: 100%; border-radius: inherit; background: var(--color-accent-progress-bar); }
   532:.customize-row { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 11px; border: 0; border-radius: var(--radius-3xl); color: #315442; background: var(--color-surface-cream); text-align: left; cursor: pointer; }
   533:.customize-row div { display: grid; gap: 2px; }
   534:.customize-row small { color: #7b817b; font-size: var(--font-size-xs); }
   535:.trick-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
   536:.trick-grid article { display: grid; gap: 5px; padding: 15px; border: 1px dashed var(--color-border-trick); border-radius: var(--radius-5xl); color: #9aa29c; }
   537:.trick-grid article.earned { border: 0; color: #57735f; background: #e7efdf; }
   538:.trick-grid small { color: #818c84; font-size: var(--font-size-xs); }
   539:
   540:/* ═══════════════════════════════════════════════════════════════════════
   541:   Souvenir / screening / activity link
   542:   ═══════════════════════════════════════════════════════════════════════ */
   543:.souvenir-row, .screening-card { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 14px; border: 0; border-radius: var(--radius-4xl); color: #274538; background: var(--color-surface-cream); text-align: left; cursor: pointer; }
   544:.souvenir-row > span, .screening-card > span { display: grid; place-items: center; width: 52px; height: 52px; border-radius: var(--radius-xl); color: #9b653a; background: #ffdab0; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   545:.souvenir-row div, .screening-card div, .activity-link div { display: grid; }
   546:.souvenir-row small, .screening-card small, .activity-link small { color: #7a847c; font-size: var(--font-size-sm); }
