   548:/* ═══════════════════════════════════════════════════════════════════════
   549:   Health / metric / weekly
   550:   ═══════════════════════════════════════════════════════════════════════ */
   551:.metric-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; margin-top: 18px; padding: 15px; border-radius: var(--radius-5xl); background: var(--color-surface-cream); }
   552:.metric-card.complete { background: var(--color-surface-sage-deep); }
   553:.metric-card h3 { margin: 2px 0; font-size: var(--font-size-2xl); }
   554:.metric-card p { margin: 0; color: #78847c; font-size: var(--font-size-sm); }
   555:.metric-card small { color: #8b6b4e; font-size: var(--font-size-xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   556:.metric-card > button { min-width: 46px; height: 38px; display: grid; place-items: center; border: 0; border-radius: var(--radius-md); color: white; background: var(--color-primary-camera); font-size: var(--font-size-md); font-weight: var(--font-weight-black); cursor: pointer; }
   557:.weekly-card { margin: 12px 0; padding: 17px; border-radius: var(--radius-6xl); background: var(--color-surface-sage); }
   558:.weekly-card .card-heading { margin-bottom: 10px; }
   559:.weekly-card h3 { margin: 0; font-size: var(--font-size-3xl); }
   560:.weekly-card p { color: #6d7d73; font-size: var(--font-size-md); line-height: 1.5; }
   561:.weekly-card > strong { display: block; padding: 10px; border-radius: var(--radius-sm); color: #5d6f63; background: white; font-size: var(--font-size-sm); }
   562:.health-bubble { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-top: 10px; padding: 12px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #294a3a; background: white; text-align: left; cursor: pointer; }
   563:.health-bubble div { display: grid; gap: 2px; }
   564:.health-bubble small { color: #7a847c; font-size: var(--font-size-sm); }
   565:.treatment-card { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; margin-bottom: 10px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); }
   566:.treatment-card div { display: grid; gap: 2px; }
   567:.treatment-card small { color: #7a847c; font-size: var(--font-size-sm); }
   568:.treatment-card button { padding: 7px 10px; border: 0; border-radius: var(--radius-xs); color: #4f6d5c; background: #e8efe4; font-size: var(--font-size-sm); font-weight: var(--font-weight-black); cursor: pointer; }
   569:.screening-card { margin-bottom: 10px; background: var(--color-surface-cream-warm); }
   570:.activity-link { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 12px; padding: 13px; border: 1px solid #e1e6de; border-radius: var(--radius-3xl); color: #284538; text-decoration: none; }
   571:
   572:/* ═══════════════════════════════════════════════════════════════════════
   573:   Festival / summary
   574:   ═══════════════════════════════════════════════════════════════════════ */
   575:.festival-card { margin-top: 18px; padding: 30px 20px; border-radius: var(--radius-7xl); color: #31583f; background: linear-gradient(145deg, #ffe7b8, #f8c9a6); text-align: center; }
   576:.festival-card h3 { margin: 10px 0 4px; font-size: var(--font-size-5xl); }
   577:.festival-card p { margin: 0; color: #766d5f; font-size: var(--font-size-md); }
   578:.summary-score { display: flex; align-items: center; justify-content: space-between; margin-top: 18px; padding: 18px; border-radius: var(--radius-5xl); color: #31583f; background: var(--color-surface-sage-deep); }
   579:.summary-score strong { font-size: var(--font-size-5xl); }
   580:.summary-score span { font-size: var(--font-size-sm); font-weight: var(--font-weight-black); }
   581:.summary-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; margin-top: 10px; }
   582:.summary-grid article { display: grid; gap: 3px; padding: 14px; border-radius: var(--radius-2xl); background: var(--color-surface-fog); }
   583:.summary-grid strong { font-size: var(--font-size-4xl); }
   584:.summary-grid small { color: #79857d; font-size: var(--font-size-xs); }
   585:.doctor-question { display: flex; align-items: center; gap: 12px; margin-top: 10px; padding: 14px; border-radius: var(--radius-3xl); color: #805b46; background: var(--color-surface-cream); }
   586:.doctor-question small { font-size: var(--font-size-2xs); font-weight: var(--font-weight-black); letter-spacing: 1px; }
   587:.doctor-question p { margin: 3px 0 0; font-size: var(--font-size-md); }
   588:
   589:/* ═══════════════════════════════════════════════════════════════════════
   590:   Settings
   591:   ═══════════════════════════════════════════════════════════════════════ */
   592:.settings-group { display: grid; gap: 9px; margin-top: 18px; }
   593:.settings-group > button { width: 100%; display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 11px; padding: 12px; border: 0; border-radius: var(--radius-3xl); color: #294a3a; background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   594:.settings-group > button:nth-child(1) { background: var(--color-surface-cream-alt); }
   595:.settings-group button div { display: grid; gap: 2px; }
   596:.settings-group small { color: #78857c; font-size: var(--font-size-sm); }
   597:.settings-note { display: flex; align-items: center; gap: 12px; margin-top: 14px; padding: 13px; border-radius: var(--radius-2xl); color: #65766b; background: var(--color-surface-stone-alt); }
   598:.settings-note p { margin: 0; font-size: var(--font-size-sm); line-height: 1.4; }
   599:
   600:/* ═══════════════════════════════════════════════════════════════════════
   601:   World picker / wardrobe
   602:   ═══════════════════════════════════════════════════════════════════════ */
   603:.world-picker { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
   604:.world-picker > button { min-width: 0; display: grid; gap: 3px; padding: 6px 6px 9px; border: 2px solid transparent; border-radius: var(--radius-3xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   605:.world-picker > button.selected { border-color: var(--color-border-world-sel); background: var(--color-surface-sage-light); }
   606:.world-picker strong { padding-inline: 3px; overflow: hidden; font-size: var(--font-size-md); text-overflow: ellipsis; white-space: nowrap; }
   607:.world-picker small { padding-inline: 3px; overflow: hidden; color: var(--color-text-faint); font-size: var(--font-size-2xs); text-overflow: ellipsis; white-space: nowrap; }
   608:
   609:.world-thumb { position: relative; height: 58px; border-radius: var(--radius-md); overflow: hidden; }
   610:.world-thumb::before, .world-thumb::after, .world-thumb i { content: ""; position: absolute; display: block; }
   611:.flat .world-thumb { background: linear-gradient(#f7c78f 0 48%, #c98555 49% 52%, #e7d3b5 53%); }
   612:.flat .world-thumb::before { left: 13%; bottom: 9px; width: 62%; height: 24px; border-radius: var(--radius-sm) var(--radius-sm) 3px 3px; background: #8caa82; }
   613:.flat .world-thumb::after { right: 10px; top: 8px; width: 17px; height: 24px; border: 3px solid rgba(255,255,255,.8); }
   614:.garden .world-thumb { background: linear-gradient(#8dc8c1 0 46%, #6b9f5b 47% 70%, #89b662 71%); }
   615:.garden .world-thumb::before { left: 11px; top: 13px; width: 22px; height: 31px; border-radius: var(--radius-full); background: #3f7b47; box-shadow: 45px 7px 0 #e194a4; }
   616:.garden .world-thumb::after { left: 42%; bottom: 0; width: 16%; height: 31px; background: #d6bf83; clip-path: polygon(40% 0,60% 0,100% 100%,0 100%); }
   617:.kampung .world-thumb { background: linear-gradient(#f5a86e 0 48%, #617d47 49%); }
   618:.kampung .world-thumb::before { left: 24%; bottom: 9px; width: 54%; height: 27px; background: #e6c184; clip-path: polygon(50% 0,100% 35%,92% 35%,92% 100%,8% 100%,8% 35%,0 35%); }
   619:.kampung .world-thumb::after { left: 44%; bottom: 9px; width: 14%; height: 16px; background: #855943; }
   620:.wardrobe-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
   621:.wardrobe-grid button { display: grid; grid-template-columns: 45px 1fr; align-items: center; gap: 1px 8px; padding: 9px; border: 2px solid transparent; border-radius: var(--radius-2xl); color: #345343; background: var(--color-surface-stone); text-align: left; cursor: pointer; }
   622:.wardrobe-grid button.selected { border-color: var(--color-border-wardrobe-sel); background: var(--color-surface-cream-selected); }
   623:.wardrobe-grid button > span { grid-row: span 2; display: grid; place-items: center; width: 43px; height: 43px; border-radius: var(--radius-xl); color: #6b826f; background: white; }
   624:.wardrobe-grid strong { font-size: var(--font-size-sm); }
   625:.wardrobe-grid small { color: var(--color-text-faint); font-size: var(--font-size-2xs); }
   626:
   627:/* ═══════════════════════════════════════════════════════════════════════
   628:   Accessory marks (mini icons in wardrobe)
   629:   ═══════════════════════════════════════════════════════════════════════ */
   630:.accessory-mark { position: relative; display: block; width: 34px; height: 26px; }
   631:.mark-glasses i { position: absolute; top: 7px; width: 14px; height: 11px; border: 4px solid #27322b; border-radius: var(--radius-full); }
   632:.mark-glasses i:first-child { left: 0; }
   633:.mark-glasses i:last-child { right: 0; }
   634:.mark-glasses::after { content: ""; position: absolute; top: 12px; left: 14px; width: 7px; border-top: 3px solid #27322b; }
   635:.mark-hat::before { content: ""; position: absolute; left: 5px; top: 3px; width: 24px; height: 16px; border-radius: 15px 15px 3px 3px; background: #e4b85e; }
   636:.mark-hat::after { content: ""; position: absolute; left: 0; top: 17px; width: 34px; height: 7px; border-radius: var(--radius-full); background: #bd793f; }
   637:.mark-bandana::before { content: ""; position: absolute; left: 3px; top: 4px; width: 28px; height: 20px; background: #d75442; clip-path: polygon(0 0,100% 0,50% 100%); }
   638:
   639:/* ═══════════════════════════════════════════════════════════════════════
   640:   Pet accessories (full-size on the dog)
   641:   ═══════════════════════════════════════════════════════════════════════ */
   642:/* Rendered inside DogStage's body, so it moves with the dog. Offsets are % of the dog figure; tune when the final dog art lands. */
   643:.pet-accessory { position: absolute; z-index: 1; left: 50%; pointer-events: none; }
   644:.accessory-glasses { top: 31%; width: 124px; height: 46px; transform: translateX(-50%) rotate(-2deg); }
   645:.accessory-glasses i { position: absolute; width: 51px; height: 36px; border: 8px solid #201f1d; border-radius: var(--radius-full); background: rgba(47,57,50,.48); box-shadow: inset 0 3px rgba(255,255,255,.25); }
   646:.accessory-glasses i:first-child { left: 5px; }
   647:.accessory-glasses i:last-child { right: 5px; }
   648:.accessory-glasses::after { content: ""; position: absolute; top: 15px; left: 53px; width: 19px; border-top: 7px solid #201f1d; }
   649:.accessory-hat { top: 24%; width: 150px; height: 70px; transform: translateX(-50%) rotate(3deg); }
   650:.accessory-hat::before { content: ""; position: absolute; left: 34px; top: 4px; width: 82px; height: 48px; border-radius: 50px 50px 8px 8px; background: repeating-linear-gradient(90deg,#e7bd65 0 5px,#d7a953 6px 8px); }
   651:.accessory-hat::after { content: ""; position: absolute; left: 0; bottom: 4px; width: 150px; height: 20px; border-radius: var(--radius-full); background: #c88143; box-shadow: inset 0 5px #f0ce79; }
   652:.accessory-bandana { top: 39%; width: 94px; height: 58px; transform: translateX(-50%); background: #d95543; clip-path: polygon(0 0,100% 0,50% 100%); filter: var(--shadow-bandana); }
   653:
   654:/* ═══════════════════════════════════════════════════════════════════════
   655:   T2: Search bar, HSA results, medication edit, explanation links
   656:   ═══════════════════════════════════════════════════════════════════════ */
   657:.search-bar { display: flex; gap: 8px; margin-top: 16px; }
   658:.search-bar input { flex: 1; min-height: 48px; padding: 8px 12px; border: 1px solid var(--color-border-card); border-radius: var(--radius-xl); color: var(--color-text-base); font: inherit; }
   659:.search-bar input:focus { outline: 2px solid var(--color-focus); outline-offset: 1px; }
   660:.hsa-results { display: grid; gap: 6px; margin-top: 14px; text-align: left; }
   661:.hsa-result-row { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 8px; padding: 12px 14px; border: 0; border-radius: var(--radius-3xl); color: var(--color-text-heading); background: var(--color-surface-sage); text-align: left; cursor: pointer; }
   662:.hsa-result-row:hover { background: var(--color-surface-sage-dark); }
   663:.hsa-result-row strong { font-size: var(--font-size-lg); }
   664:.hsa-result-row small { display: block; color: var(--color-text-body); font-size: var(--font-size-sm); }
   665:.hsa-credit { margin-top: 12px; color: var(--color-text-faint); font-size: var(--font-size-xs); line-height: 1.4; text-align: left; }
   666:.no-results { text-align: center; margin-top: 18px; }
   667:.no-results p { color: var(--color-text-body); font-size: var(--font-size-lg); }
