     8:
     9:/**
    10: * Presentational: receives the current reaction as a prop and renders it.
    11: * Layers, back to front: glow → cast shadow → contact shadow → dog (+ accessory overlay)
    12: * → reaction overlay (hearts, dizzy stars). The speech bubble lives outside the dog (PetBubble), so it never covers the head.
    13: */
    14:export function DogStage({
    15:  mood,
    16:  dogName,
    17:  dizzy,
    18:  onPet,
    19:  reaction,
    20:  accessory,
    21:}: {
    22:  mood: DogMood;
