    30:  const image = useImageWithFallback(DOG_IMAGE_BY_MOOD[mood], DOG_BASE_IMAGE);
    31:  const look = MOOD_LOOKS[mood];
    32:
    33:  if (!image.available) return <div className="dog-stage" />;
    34:
    35:  const reactionClass = reaction ? ` is-${reaction}` : "";
    36:  const dizzyClass = dizzy ? " is-dizzy" : "";
    37:
    38:  return (
    39:    <div className={`dog-stage dog-stage--${mood}`} style={{ "--dog-glow": look.glow } as CSSProperties}>
    40:      <div className="dog-stage__figure">
    41:        <span className="dog-stage__glow" aria-hidden="true" />
    42:        <span className="dog-stage__cast-shadow" aria-hidden="true" />
    43:        <span className="dog-stage__contact-shadow" aria-hidden="true" />
    44:        {reaction === "hearts" && (
    45:          <span className="dog-stage__hearts" aria-hidden="true">
    46:            {Array.from({ length: HEART_BURST_COUNT }, (_, index) => (
    47:              <span className={`dog-stage__heart dog-stage__heart--${index + 1}`} key={index}><Icon name="heart" size={30} /></span>
    48:            ))}
    49:          </span>
    50:        )}
    51:        {dizzy && (
    52:          // Each star rides two nested movers (x and y, a quarter-cycle apart), which traces an ellipse around the head.
    53:          <span className="dog-stage__stars" aria-hidden="true">
    54:            {[1, 2, 3].map((star) => (
    55:              <span className={`dog-stage__orbit dog-stage__orbit--${star}`} key={star}>
    56:                <span className="dog-stage__orbit-y">
    57:                  <span className="dog-stage__star"><Icon name="star" size={26} /></span>
    58:                </span>
    59:              </span>
    60:            ))}
    61:          </span>
    62:        )}
    63:        <button
    64:          type="button"
    65:          className={`dog-stage__pet${reactionClass}${dizzyClass}`}
    66:          onClick={dizzy ? undefined : onPet}
    67:          aria-label={dogName}
    68:        >
    69:          <span className="dog-stage__body">
    70:            <img className="dog-stage__image" src={image.src} alt="" onError={image.onError} draggable={false} />
    71:            {accessory}
    72:          </span>
    73:        </button>
    74:      </div>
    75:    </div>
    76:  );
    77:}
